INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-023', 'SW', 'P3', 'OPEN', NULL, NULL, 'GAP-019 RESOLVED 2026-09-18, AND HALF OF WHAT IT CLAIMED WAS AN INSTRUMENTATION ERROR OF MINE THAT MUST BE RETRACTED. THE REAL DEFECT, FIXED: the gate cap at assess_cell.py (state stated + any binding gate -> provisional) downgraded the cell WITHOUT supplying the confidence flag that provisional requires, so EvidenceStateRecord refused it as an uncaught pydantic traceback and nothing was written. The anchored branch sets state=stated and leaves conf None, which is correct for a stated cell; the cap then moved the state and left conf behind it. determination_gates held ZERO rows until batch 16 raised gate 1, so this branch had NEVER EXECUTED in the engine life -- the defect was created by the first gate ever raised, which was mine. NOT A DOCTRINE QUESTION, which is what GAP-019 claimed it was: the fix is descriptive, present is the anchoring basis the cell already has and absent names the gate that caps it, both read off state the function already holds. A second bug rode along -- the flag read the gate dict key detail where derivation_handshake names it why, so the first version named the gate and then said nothing about it. WHAT IS RETRACTED: GAP-019 second half asserted that a single T1 claim DISPLACED the entire regulatory stratum, citing governing and supporting both None. THAT IS FALSE AND THE CAUSE WAS MY PROBE, NOT THE ENGINE. I printed det.get(governing); the key is governing_refs, and it reads [REF-01002] correctly. Re-measured: governing_refs=[REF-01002], tier_basis=T1, supporting_refs=[]. The regulatory sources dropping OUT of the governing set once an anchor exists is the RATIFIED LADDER working -- T4-T6 are walled off from full-strength anchoring -- not a defect and not displacement. The claim reached GAP-019, the session record, the attestation and the PR body; all four are corrected. CLAUDE.md rule 7a applies to a figure read off a dict key as much as to one typed by hand.', '2026-09-18 21:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 21:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-024', 'AUDT', 'P1', 'OPEN', NULL, NULL, 'GAP-020 IS NOT CLOSED BY THE GAP-019 FIX, AND THE REASON IS NOW MECHANICAL RATHER THAN A JUDGEMENT CALL. With the engine repaired, re-determining parameter 3 x MOB was REHEARSED on a throwaway copy and it succeeds: state=provisional, value_max 7.0 percent, unit percent, tier_basis T1, governing_refs [REF-01002], rests_on_proxy_inference 0, with the cap recorded in the confidence flag naming gate 1. K01 and K02 return to 1 subject each, so two of the three vacuous checks GAP-020 records would be answered. BUT C10 THEN FAILS: no published cell rests on an unverified or disputed source -- 1 examined, 1 unsound -- because REF-01002 is UNVERIFIED, the grade batch 16 gave it after I4 caught the original VERIFIED as wrong (the article was never retrieved, only its TRID record). test_db_integrity goes 73/74 on the rehearsal. SO THE REPOSITORY OWN BLOCKING CHECK REFUSES THE RE-DETERMINATION, and it refuses it for exactly the reason batch 16 refused it by hand. That is the strongest possible form of the earlier caution: it is no longer my judgement that the cell should not be determined on an unread abstract, it is C10. THE EMPTY DETERMINATION SURFACE IS THEREFORE CORRECT UNTIL GAP-016 CLOSES, and the path out is now fully specified: read REF-01002 full text, verify it, re-determine, C10 passes, resolve gate 1. Nothing else is owed and nothing should be forced. DO NOT apply the rehearsed determination: it is in a scratch copy only, canonical is untouched, and applying it would turn a blocking gate red to fill a surface that is honestly empty.', '2026-09-18 21:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 21:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-025', 'RP', 'P1', 'OPEN', NULL, NULL, 'BATCH 17 MINING ASSIGNMENT — owner instruction 2026-09-18, answering GAP-022: "then assign the mining for the next batch". THE MECHANISM FOR "runs eventually" IS ASSIGNMENT, NOT AN AGEING METRIC. GAP-022 named the missing half of the 2026-09-18 ruling (deferred is okay so long as it runs eventually) and proposed building an age or backlog measure. The owner answered by assigning the work instead, which is the cheaper and more honest instrument: a deferral runs because a batch is told to run it, not because a counter goes red. DERIVE THE BACKLOG, NEVER QUOTE IT -- select slug, global_ref_id, deferred_reason from citation_mining where deferred_reason is not null; measured 2026-09-18 at ten rows, all on accessible-circulation-geometry. BATCH 17 TAKES THESE, IN THIS ORDER, AND THE ORDER IS REASONED. (1) REF-01002 backward -- the highest-value target on the slug by its own framing, a 2009 study saying design recommendations for either the running slope or the cross slope requirements are based on limited empirical research, so it cites whatever empirical work existed. BLOCKED BEHIND GAP-016: no DOI, therefore no Crossref deposit, so its reference list can only come from the article, which GAP-016 must obtain anyway to settle C10. Reading it discharges both. (2) REF-00979 backward -- ranks second on the GAP-018 predictor (a paper cites the literature of its own independent variable; Chow et al. measure propulsion across a slope series), and mining it is therefore also a PROSPECTIVE TEST of that predictor, with the prediction already recorded in its deferral note before the pass. (3) REF-00980 backward -- a 1997 paper cites pre-1997 work, and the pre-1997 ramp-slope literature is exactly what REF-01002 abstract calls limited; expected yield modest, stated in advance. (4) REF-00983 and REF-00986 backward -- batch 08 deferrals, the oldest in the register, and REF-00986 own extraction is graded absent so its references are unlikely to be gradient-bearing; both cheap. (5) REF-00999, REF-01000, REF-01001 backward -- T3, so R2 depth-2-3 obligation over CONFIRMED T1-T2 anchors reaches them only secondarily; take them only if capacity remains. (6) REF-00989 and REF-00993 FORWARD -- both Japanese-language, no DOI, absent from every citation index, so the forward graph does not reach them. THESE TWO ARE NOT A MINING PASS AND MUST NOT BE DRESSED AS ONE: the tractable equivalent is a Japanese-language site search for organisations quoting the same framing, which is a SEARCH and is recorded as owed. WHAT DISCHARGE REQUIRES: a pass that runs clears its deferral only with --discharge-deferral, which asserts the standing deferral belongs to the direction just run; without it the deferral stands and log-mining prints deferral_still_standing. Batch 17 closes this gap by emptying the backlog or by re-deferring with fresh reasons -- never by silence.', '2026-09-18 21:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 21:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, NULL, NULL, NULL);
